Let's define a script to solve the system of congruences using the Chinese Remainder Theorem.

```python
from functools import reduce

def extended_gcd(a, b):
    if a == 0:
        return (b, 0, 1)
    else:
        g, y, x = extended_gcd(b % a, a)
        return (g, x - (b // a) * y, y)

def mod_inv(a, m):
    g, x, _ = extended_gcd(a, m)
    if g != 1:
        raise ValueError("Inverse doesn't exist")
    else:
        return x % m

def chinese_remainder_theorem(remainders, moduli):
    total = 0
    prod = reduce(lambda a, b: a * b, moduli)

    for rem, mod in zip(remainders, moduli):
        p = prod // mod
        inv = mod_inv(p, mod)
        total += rem * inv * p

    return total % prod

def solve(inputs: dict) -> float:
    remainders = inputs['REMAINDERS']
    moduli = inputs['MODULI']

    result = chinese_remainder_theorem(remainders, moduli)
    return round(result, 16)

